const BASE = "http://localhost:8000";

export async function fetchBooks() {
  const res = await fetch(`${BASE}/books`);
  if (!res.ok) throw new Error("Failed to fetch books");
  return res.json();
}

export async function addBook(book) {
  const res = await fetch(`${BASE}/books`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(book),
  });
  if (!res.ok) {
    const err = await res.json().catch(() => ({}));
    throw new Error(err.detail || "Failed to add book");
  }
  return res.json();
}

export async function updateStatus(id, status) {
  const res = await fetch(`${BASE}/books/${id}`, {
    method: "PATCH",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ status }),
  });
  if (!res.ok) throw new Error("Failed to update book");
  return res.json();
}

export async function deleteBook(id) {
  const res = await fetch(`${BASE}/books/${id}`, { method: "DELETE" });
  if (!res.ok) throw new Error("Failed to delete book");
}

import { useState, useEffect, useCallback } from "react";
import { fetchBooks, addBook, updateStatus, deleteBook } from "./api";
import AddBookForm from "./components/AddBookForm";
import BookList from "./components/BookList";
import FilterBar from "./components/FilterBar";
import "./App.css";

const FILTERS = ["all", "to-read", "reading", "done"];

export default function App() {
  const [books, setBooks] = useState([]);
  const [filter, setFilter] = useState("all");
  const [error, setError] = useState(null);
  const [loading, setLoading] = useState(true);

  const load = useCallback(async () => {
    try {
      setLoading(true);
      const data = await fetchBooks();
      setBooks(data);
      setError(null);
    } catch (e) {
      setError(e.message);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    load();
  }, [load]);

  const handleAdd = async (book) => {
    try {
      const created = await addBook(book);
      setBooks((prev) => [created, ...prev]);
      setError(null);
    } catch (e) {
      setError(e.message);
    }
  };

  const handleStatusChange = async (id, status) => {
    try {
      const updated = await updateStatus(id, status);
      setBooks((prev) => prev.map((b) => (b.id === id ? updated : b)));
      setError(null);
    } catch (e) {
      setError(e.message);
    }
  };

  const handleDelete = async (id) => {
    try {
      await deleteBook(id);
      setBooks((prev) => prev.filter((b) => b.id !== id));
      setError(null);
    } catch (e) {
      setError(e.message);
    }
  };

  const visible =
    filter === "all" ? books : books.filter((b) => b.status === filter);

  const counts = {
    all: books.length,
    "to-read": books.filter((b) => b.status === "to-read").length,
    reading: books.filter((b) => b.status === "reading").length,
    done: books.filter((b) => b.status === "done").length,
  };

  return (
    <div className="app">
      <header className="app-header">
        <h1>📚 BookTrack</h1>
        <p className="subtitle">la tua libreria personale</p>
      </header>

      <main className="app-main">
        <AddBookForm onAdd={handleAdd} />

        {error && (
          <div className="error-banner">
            ⚠️ {error}
            <button onClick={() => setError(null)}>✕</button>
          </div>
        )}

        <FilterBar
          filters={FILTERS}
          active={filter}
          counts={counts}
          onChange={setFilter}
        />

        {loading ? (
          <div className="loading">Caricamento…</div>
        ) : (
          <BookList
            books={visible}
            onStatusChange={handleStatusChange}
            onDelete={handleDelete}
          />
        )}
      </main>
    </div>
  );
}

import { useState } from "react";

const STATUSES = [
  { value: "to-read", label: "📋 Da leggere" },
  { value: "reading", label: "📖 In lettura" },
  { value: "done",    label: "✅ Letto" },
];

export default function AddBookForm({ onAdd }) {
  const [title, setTitle]   = useState("");
  const [author, setAuthor] = useState("");
  const [status, setStatus] = useState("to-read");
  const [busy, setBusy]     = useState(false);

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!title.trim() || !author.trim()) return;
    setBusy(true);
    await onAdd({ title: title.trim(), author: author.trim(), status });
    setTitle("");
    setAuthor("");
    setStatus("to-read");
    setBusy(false);
  };

  return (
    <form className="add-form" onSubmit={handleSubmit}>
      <h2>Aggiungi libro</h2>
      <div className="form-row">
        <input
          className="input"
          type="text"
          placeholder="Titolo *"
          value={title}
          onChange={(e) => setTitle(e.target.value)}
          required
        />
        <input
          className="input"
          type="text"
          placeholder="Autore *"
          value={author}
          onChange={(e) => setAuthor(e.target.value)}
          required
        />
        <select
          className="select"
          value={status}
          onChange={(e) => setStatus(e.target.value)}
        >
          {STATUSES.map((s) => (
            <option key={s.value} value={s.value}>
              {s.label}
            </option>
          ))}
        </select>
        <button className="btn btn-primary" type="submit" disabled={busy}>
          {busy ? "…" : "Aggiungi"}
        </button>
      </div>
    </form>
  );
}

const LABELS = {
  all:      "Tutti",
  "to-read": "Da leggere",
  reading:  "In lettura",
  done:     "Letti",
};

export default function FilterBar({ filters, active, counts, onChange }) {
  return (
    <div className="filter-bar">
      {filters.map((f) => (
        <button
          key={f}
          className={`filter-btn ${active === f ? "active" : ""}`}
          onClick={() => onChange(f)}
        >
          {LABELS[f]}
          <span className="badge">{counts[f]}</span>
        </button>
      ))}
    </div>
  );
}

import BookCard from "./BookCard";

export default function BookList({ books, onStatusChange, onDelete }) {
  if (books.length === 0) {
    return <p className="empty">Nessun libro in questa categoria.</p>;
  }

  return (
    <ul className="book-list">
      {books.map((book) => (
        <BookCard
          key={book.id}
          book={book}
          onStatusChange={onStatusChange}
          onDelete={onDelete}
        />
      ))}
    </ul>
  );
}

import { useState } from "react";

const STATUS_META = {
  "to-read": { label: "Da leggere", icon: "📋", next: "reading",  nextLabel: "Inizia a leggere →" },
  reading:   { label: "In lettura", icon: "📖", next: "done",     nextLabel: "Segna come letto ✓" },
  done:      { label: "Letto",      icon: "✅", next: "to-read",  nextLabel: "Rimetti in lista ↺" },
};

export default function BookCard({ book, onStatusChange, onDelete }) {
  const [busy, setBusy] = useState(false);
  const meta = STATUS_META[book.status];

  const handleNext = async () => {
    setBusy(true);
    await onStatusChange(book.id, meta.next);
    setBusy(false);
  };

  const handleDelete = async () => {
    if (!confirm(`Eliminare "${book.title}"?`)) return;
    await onDelete(book.id);
  };

  return (
    <li className={`book-card status-${book.status}`}>
      <div className="book-icon">{meta.icon}</div>
      <div className="book-info">
        <span className="book-title">{book.title}</span>
        <span className="book-author">{book.author}</span>
        <span className={`status-badge status-${book.status}`}>{meta.label}</span>
      </div>
      <div className="book-actions">
        <button
          className="btn btn-next"
          onClick={handleNext}
          disabled={busy}
          title={meta.nextLabel}
        >
          {busy ? "…" : meta.nextLabel}
        </button>
        <button
          className="btn btn-delete"
          onClick={handleDelete}
          title="Elimina"
        >
          🗑
        </button>
      </div>
    </li>
  );
}

/* ---- Reset & base ---- */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --bg:         #0f1117;
  --surface:    #1a1d27;
  --surface2:   #22263a;
  --border:     #2e3350;
  --accent:     #6c63ff;
  --accent-h:   #857dff;
  --text:       #e8eaf6;
  --text-muted: #8b90b0;
  --red:        #ff5370;
  --green:      #a3e635;
  --yellow:     #ffd166;
  --radius:     10px;
  --shadow:     0 4px 24px rgba(0,0,0,.45);
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: "Inter", system-ui, sans-serif;
  min-height: 100vh;
}

/* ---- Layout ---- */
.app { max-width: 820px; margin: 0 auto; padding: 2rem 1rem 4rem; }

.app-header {
  text-align: center;
  margin-bottom: 2.5rem;
}
.app-header h1 { font-size: 2.2rem; font-weight: 700; letter-spacing: -.5px; }
.subtitle { color: var(--text-muted); margin-top: .35rem; }

.app-main { display: flex; flex-direction: column; gap: 1.5rem; }

/* ---- Add form ---- */
.add-form {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 1.4rem 1.6rem;
  box-shadow: var(--shadow);
}
.add-form h2 { font-size: 1rem; color: var(--text-muted); margin-bottom: 1rem; }

.form-row {
  display: flex;
  gap: .75rem;
  flex-wrap: wrap;
}

.input, .select {
  background: var(--surface2);
  border: 1px solid var(--border);
  border-radius: 7px;
  color: var(--text);
  padding: .55rem .85rem;
  font-size: .93rem;
  outline: none;
  transition: border-color .2s;
}
.input:focus, .select:focus { border-color: var(--accent); }
.input { flex: 1 1 160px; }
.select { flex: 0 0 auto; }

/* ---- Buttons ---- */
.btn {
  border: none;
  border-radius: 7px;
  cursor: pointer;
  font-size: .88rem;
  font-weight: 600;
  padding: .55rem 1rem;
  transition: background .18s, opacity .18s;
}
.btn:disabled { opacity: .5; cursor: not-allowed; }

.btn-primary {
  background: var(--accent);
  color: #fff;
}
.btn-primary:hover:not(:disabled) { background: var(--accent-h); }

.btn-next {
  background: var(--surface2);
  color: var(--text);
  border: 1px solid var(--border);
  white-space: nowrap;
}
.btn-next:hover:not(:disabled) { border-color: var(--accent); color: var(--accent-h); }

.btn-delete {
  background: transparent;
  color: var(--text-muted);
  border: 1px solid transparent;
  padding: .55rem .7rem;
}
.btn-delete:hover { color: var(--red); border-color: var(--red); }

/* ---- Filter bar ---- */
.filter-bar {
  display: flex;
  gap: .5rem;
  flex-wrap: wrap;
}

.filter-btn {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 20px;
  color: var(--text-muted);
  cursor: pointer;
  font-size: .85rem;
  padding: .4rem 1rem;
  display: flex;
  align-items: center;
  gap: .45rem;
  transition: all .18s;
}
.filter-btn:hover { border-color: var(--accent); color: var(--text); }
.filter-btn.active { background: var(--accent); border-color: var(--accent); color: #fff; }

.badge {
  background: rgba(255,255,255,.15);
  border-radius: 10px;
  font-size: .75rem;
  padding: .05rem .45rem;
  min-width: 1.4rem;
  text-align: center;
}
.filter-btn.active .badge { background: rgba(255,255,255,.25); }

/* ---- Book list ---- */
.book-list { list-style: none; display: flex; flex-direction: column; gap: .75rem; }

.book-card {
  display: flex;
  align-items: center;
  gap: 1rem;
  background: var(--surface);
  border: 1px solid var(--border);
  border-left: 4px solid var(--border);
  border-radius: var(--radius);
  padding: .9rem 1.1rem;
  transition: border-color .2s, box-shadow .2s;
}
.book-card:hover { box-shadow: var(--shadow); }

.book-card.status-to-read  { border-left-color: var(--yellow); }
.book-card.status-reading  { border-left-color: var(--accent); }
.book-card.status-done     { border-left-color: var(--green); }

.book-icon { font-size: 1.5rem; flex-shrink: 0; }

.book-info {
  display: flex;
  flex-direction: column;
  gap: .2rem;
  flex: 1;
  min-width: 0;
}
.book-title {
  font-size: 1rem;
  font-weight: 600;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.book-author { font-size: .85rem; color: var(--text-muted); }

.status-badge {
  font-size: .72rem;
  font-weight: 700;
  letter-spacing: .04em;
  text-transform: uppercase;
  padding: .15rem .5rem;
  border-radius: 4px;
  width: fit-content;
}
.status-badge.status-to-read  { background: rgba(255,209,102,.15); color: var(--yellow); }
.status-badge.status-reading   { background: rgba(108,99,255,.2);  color: var(--accent-h); }
.status-badge.status-done      { background: rgba(163,230,53,.15); color: var(--green); }

.book-actions { display: flex; gap: .5rem; align-items: center; flex-shrink: 0; }

/* ---- Misc ---- */
.error-banner {
  background: rgba(255,83,112,.15);
  border: 1px solid var(--red);
  border-radius: var(--radius);
  color: var(--red);
  padding: .75rem 1rem;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 1rem;
}
.error-banner button {
  background: none;
  border: none;
  color: var(--red);
  cursor: pointer;
  font-size: 1rem;
}

.loading, .empty {
  text-align: center;
  color: var(--text-muted);
  padding: 2rem;
}

/* ---- Responsive ---- */
@media (max-width: 600px) {
  .book-card { flex-wrap: wrap; }
  .book-actions { width: 100%; justify-content: flex-end; }
  .form-row { flex-direction: column; }
  .input, .select { width: 100%; }
}

